import React, { useState, useEffect } from 'react';
import { getStore1AllSales, createStore1Sale } from '../../services/stockService';

const SalesOperations = () => {
    const [sales, setSales] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const [saleForm, setSaleForm] = useState({
        quantity: 0,
        totalPrice: 0,
        customerName: '',
        customerPhone: '',
        paymentMethod: 'Credit Card' // Varsayılan ödeme yöntemi
    });

    useEffect(() => {
        fetchSales();
    }, []);

    const fetchSales = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await getStore1AllSales();

            if (!response || !response.success) {
                throw new Error(response?.message || 'Satış verisi alınamadı');
            }

            setSales(response.store1Sales || []);
        } catch (err) {
            console.error('Satış verisi yüklenirken hata:', err);
            setError(err.message || 'Satış verileri yüklenirken bir hata oluştu');
            setSales([]);
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const response = await createStore1Sale(saleForm);
            if (response.success) {
                setSaleForm({
                    quantity: 0,
                    totalPrice: 0,
                    customerName: '',
                    customerPhone: '',
                    paymentMethod: 'Credit Card'
                });
                fetchSales();
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('Satış oluşturulurken bir hata oluştu');
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setSaleForm(prev => ({
            ...prev,
            [name]: value
        }));
    };

    if (loading) return (
        <div className="flex justify-center items-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div>
        </div>
    );

    if (error) return (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
            <strong className="font-bold">Hata!</strong>
            <span className="block sm:inline"> {error}</span>
        </div>
    );

    return (
        <div className="space-y-6">
            {/* Satış Ekleme Formu */}
            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Yeni Satış Ekle</h2>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Müşteri Adı</label>
                            <input
                                type="text"
                                name="customerName"
                                value={saleForm.customerName}
                                onChange={handleInputChange}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Telefon</label>
                            <input
                                type="text"
                                name="customerPhone"
                                value={saleForm.customerPhone}
                                onChange={handleInputChange}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                                placeholder="+90 XXX XXX XX XX"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Miktar</label>
                            <input
                                type="number"
                                name="quantity"
                                value={saleForm.quantity}
                                onChange={handleInputChange}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                                min="1"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Toplam Fiyat</label>
                            <input
                                type="number"
                                name="totalPrice"
                                value={saleForm.totalPrice}
                                onChange={handleInputChange}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                                min="0"
                                step="0.01"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Ödeme Yöntemi</label>
                            <select
                                name="paymentMethod"
                                value={saleForm.paymentMethod}
                                onChange={handleInputChange}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                            >
                                <option value="Credit Card">Kredi Kartı</option>
                                <option value="Cash">Nakit</option>
                                <option value="Bank Transfer">Banka Transferi</option>
                            </select>
                        </div>
                    </div>
                    <div className="flex justify-end">
                        <button
                            type="submit"
                            className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                        >
                            Satış Ekle
                        </button>
                    </div>
                </form>
            </div>

            {/* Satış Listesi */}
            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Satış Listesi</h2>
                {sales.length === 0 ? (
                    <div className="text-center text-gray-500 py-4">
                        Henüz satış kaydı bulunmamaktadır.
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-200">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Müşteri Adı
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Telefon
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Miktar
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Toplam Fiyat
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Ödeme Yöntemi
                                    </th>
                                </tr>
                            </thead>
                            <tbody className="bg-white divide-y divide-gray-200">
                                {sales.map((sale) => (
                                    <tr key={sale.id} className="hover:bg-gray-50">
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {sale.customerName}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {sale.customerPhone}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {sale.quantity}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' })
                                                .format(sale.totalPrice)}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {sale.paymentMethod}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default SalesOperations;
